//! Temporal neural denoiser (`--temporal-model FILE.wgsl`, generated by
//! training/temporal/export.py). Every frame traces one fresh sample per pixel;
//! the generated kernels reproject the previous output with the motion vectors,
//! run the network and its à-trous kernels, and write the display image and the
//! history for the next frame.
#![allow(clippy::cast_possible_truncation)]

/// Entry points of a generated model, in dispatch order (filter levels vary).
pub fn kernels(source: &str) -> Vec<String> {
    let mut names = vec!["csTdFeatures".to_owned()];
    if constant(source, "TD_HALF", 0) != 0 {
        names.push("csTdPool".to_owned());
    }
    names.extend(["csTdConv1", "csTdConv2", "csTdBlend"].map(str::to_owned));
    let levels = source.matches("fn csTdFilter").count();
    names.extend((0..levels).map(|l| format!("csTdFilter{l}")));
    if source.contains("fn csTdEmission") {
        names.push("csTdEmission".to_owned());
    }
    names
}

/// Runs after the model: adds back the directly visible emission (kept out of the
/// denoiser's input, see raytracer.wgsl `DENOISER_INPUT`), and converges while the
/// view is still: the raw frames (noisy input + emission) are averaged from the first
/// still frame (`tdParams.pad1` counts them) and the display fades from the denoised
/// frame to that unbiased mean, half way after `TD_CONVERGE_FRAMES` frames.
const EMISSION_KERNEL: &str = "
const TD_CONVERGE_FRAMES = 64.;
@group(5) @binding(10) var<storage, read_write> tdAccumulated: array<vec4<f32>>;
@compute @workgroup_size(8, 8)
fn csTdEmission(@builtin(global_invocation_id) id: vec3<u32>) {
    if id.x >= frameData.x || id.y >= frameData.y { return; }
    let i = frameData.x * id.y + id.x;
    let e = gbuffer[frameData.x * frameData.y * 3u + i].xyz;
    let o = tdOutput[i];
    let denoised = vec3(o[0], o[1], o[2]) + e;
    let still = tdParams.pad1;
    let raw = vec3(imageBuffer[i][0], imageBuffer[i][1], imageBuffer[i][2]) + e;
    let sum = select(vec3(0.), tdAccumulated[i].xyz, still > 1u) + raw;
    tdAccumulated[i] = vec4(sum, 0.);
    // The first few still frames show the denoiser alone (no single-sample fireflies).
    let n = f32(max(still, 4u) - 4u);
    let result = mix(denoised, sum / f32(max(still, 1u)), n / (n + TD_CONVERGE_FRAMES));
    tdOutput[i] = array<f32, 3>(result.r, result.g, result.b);
}
";

/// A `const NAME = Nu;` declared by a generated model.
fn constant(source: &str, name: &str, default: u32) -> u32 {
    source
        .split(&format!("const {name} = "))
        .nth(1)
        .and_then(|rest| rest.split('u').next())
        .map_or(default, |n| n.trim().parse().unwrap())
}

pub struct TemporalDenoiser {
    layout: wgpu::BindGroupLayout,
    params: wgpu::Buffer,
    weights: wgpu::Buffer,
    group: wgpu::BindGroup,
    pub empty_group: wgpu::BindGroup,
    pipelines: Vec<wgpu::ComputePipeline>,
    history_valid: bool,
    /// Frames since the view last changed (1 = the first frame of a new view).
    still: u32,
    /// Frame counter: selects which half of the guide buffer is this frame's.
    frame: u32,
    /// Bytes per pixel of each hidden layer.
    hidden: u64,
    /// Pixels per invocation along x in the conv kernels.
    conv_pixels: u32,
    /// Pool and conv kernels run on a half-resolution grid.
    half: bool,
}

pub fn model_source() -> Option<String> {
    crate::argument_value("--temporal-model").map(|path| {
        std::fs::read_to_string(path).expect("cannot read temporal model WGSL") + EMISSION_KERNEL
    })
}

/// The model's weights: little-endian f32 vec4s next to the WGSL (same stem, `.bin`).
fn model_weights() -> Vec<u8> {
    let path = std::path::PathBuf::from(crate::argument_value("--temporal-model").unwrap())
        .with_extension("bin");
    std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

impl TemporalDenoiser {
    pub fn layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
        // 0-7 model state and output, 10 the still-view accumulation.
        let mut entries: Vec<_> = (0..8)
            .chain([10])
            .map(|binding| wgpu::BindGroupLayoutEntry {
                binding,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            })
            .collect();
        entries.push(wgpu::BindGroupLayoutEntry {
            binding: 9,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Buffer {
                ty: wgpu::BufferBindingType::Uniform,
                has_dynamic_offset: false,
                min_binding_size: None,
            },
            count: None,
        });
        entries.push(wgpu::BindGroupLayoutEntry {
            binding: 8,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Buffer {
                ty: wgpu::BufferBindingType::Uniform,
                has_dynamic_offset: false,
                min_binding_size: None,
            },
            count: None,
        });
        device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("temporal denoiser layout"),
            entries: &entries,
        })
    }

    pub fn new(
        device: &wgpu::Device,
        layout: wgpu::BindGroupLayout,
        empty_layout: &wgpu::BindGroupLayout,
        pipelines: Vec<wgpu::ComputePipeline>,
        output: &wgpu::Buffer,
        pixels: u32,
        source: &str,
    ) -> Self {
        let hidden = 4 * u64::from(constant(source, "TD_CHANNELS", 16));
        let conv_pixels = constant(source, "TD_CONV_PIXELS", 1);
        let half = constant(source, "TD_HALF", 0) != 0;
        use wgpu::util::DeviceExt;
        let weights = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("temporal denoiser weights"),
            contents: &model_weights(),
            usage: wgpu::BufferUsages::UNIFORM,
        });
        let params = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("temporal denoiser parameters"),
            size: 16,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let group = Self::bind(device, &layout, &params, &weights, output, pixels, hidden);
        let empty_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: empty_layout,
            entries: &[],
        });
        Self {
            layout,
            params,
            weights,
            group,
            empty_group,
            pipelines,
            history_valid: false,
            still: 0,
            frame: 0,
            hidden,
            conv_pixels,
            half,
        }
    }

    fn bind(
        device: &wgpu::Device,
        layout: &wgpu::BindGroupLayout,
        params: &wgpu::Buffer,
        weights: &wgpu::Buffer,
        output: &wgpu::Buffer,
        pixels: u32,
        hidden: u64,
    ) -> wgpu::BindGroup {
        let n = u64::from(pixels.max(1));
        // history, previous guides, features, conv1, conv2, filter ping-pong, warp,
        // then the still-view accumulation (binding 10)
        let sizes = [
            16 * n,
            32 * n,
            64 * n,
            hidden * n,
            hidden * n,
            32 * n,
            16 * n,
            16 * n,
        ];
        let buffers: Vec<_> = sizes
            .iter()
            .map(|&size| {
                device.create_buffer(&wgpu::BufferDescriptor {
                    label: Some("temporal denoiser state"),
                    size,
                    usage: wgpu::BufferUsages::STORAGE,
                    mapped_at_creation: false,
                })
            })
            .collect();
        let mut entries: Vec<_> = buffers
            .iter()
            .enumerate()
            .map(|(i, b)| wgpu::BindGroupEntry {
                binding: if i == 7 { 10 } else { i as u32 },
                resource: b.as_entire_binding(),
            })
            .collect();
        entries.push(wgpu::BindGroupEntry {
            binding: 7,
            resource: output.as_entire_binding(),
        });
        entries.push(wgpu::BindGroupEntry {
            binding: 8,
            resource: params.as_entire_binding(),
        });
        entries.push(wgpu::BindGroupEntry {
            binding: 9,
            resource: weights.as_entire_binding(),
        });
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("temporal denoiser bindings"),
            layout,
            entries: &entries,
        })
    }

    /// Rebind after a resize; history restarts.
    pub fn resize(&mut self, device: &wgpu::Device, output: &wgpu::Buffer, pixels: u32) {
        self.group = Self::bind(
            device,
            &self.layout,
            &self.params,
            &self.weights,
            output,
            pixels,
            self.hidden,
        );
        self.history_valid = false;
        self.still = 0;
    }

    /// The camera or render parameters changed: restart the still-view accumulation.
    pub fn moved(&mut self) {
        self.still = 0;
    }

    /// Upload per-frame parameters; call before encoding the frame.
    pub fn prepare(&mut self, queue: &wgpu::Queue) {
        self.frame = self.frame.wrapping_add(1);
        self.still = self.still.saturating_add(1);
        let params = [u32::from(self.history_valid), self.frame & 1, self.still, 0];
        queue.write_buffer(&self.params, 0, bytemuck::cast_slice(&params));
        self.history_valid = true;
    }

    /// Groups 0-3 must be bound to the tracing groups.
    pub fn record(&self, pass: &mut wgpu::ComputePass<'_>, size: (u32, u32)) {
        pass.set_bind_group(4, &self.empty_group, &[]);
        pass.set_bind_group(5, &self.group, &[]);
        // RT_TD_KERNELS=k dispatches only the first k kernels (profiling by elimination).
        let count =
            std::env::var("RT_TD_KERNELS").map_or(self.pipelines.len(), |v| v.parse().unwrap());
        // Kernel order: features, [pool], conv1, conv2, blend, filters...
        let first_conv = if self.half { 2 } else { 1 };
        for (index, pipeline) in self.pipelines.iter().enumerate().take(count) {
            let conv = index == first_conv || index == first_conv + 1;
            let grid = if self.half && (conv || index == 1) {
                (size.0.div_ceil(2), size.1.div_ceil(2))
            } else {
                size
            };
            let per_thread = if conv { self.conv_pixels } else { 1 };
            pass.set_pipeline(pipeline);
            pass.dispatch_workgroups(grid.0.div_ceil(8 * per_thread), grid.1.div_ceil(8), 1);
        }
    }
}
